window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[211]={"id":"211","numero":211,"titre":"Sarcoïdose","objectifs":[{"id":"211-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la sarcoïdose","contenu":"<p>La <span class=\"kw-def\">sarcoïdose</span> est une <span class=\"kw-def\">granulomatose systémique de cause inconnue</span>. Elle se définit par l'<span class=\"kw-ttt\">infiltration</span> des organes atteints par des <strong><span class=\"kw-def\">granulomes immuns épithélioïdes et giganto-cellulaires sans nécrose caséeuse</span></strong>.</p>\n      <ul>\n        <li>Ces granulomes sont aussi nommés <span class=\"kw-def\">granulomes tuberculoïdes</span> — à ne pas confondre avec le <strong>granulome tuberculeux</strong> qui, lui, comporte une <span class=\"kw-alerte\">nécrose caséeuse</span> centrale.</li>\n        <li>Le diagnostic de <span class=\"kw-clinique\">sarcoïdose</span> est par essence un <strong>diagnostic d'élimination</strong> : il impose d'écarter toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">autres causes de granulomes</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Composition du granulome sarcoïdien</h4>\n      <table >\n        <thead><tr><th>Constituant</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Follicule central</td><td><strong>Cellules épithélioïdes :</strong> macrophages d'aspect épithélial <br><strong>Cellules géantes :</strong> cellules de Langhans, multinucléées, noyaux disposés en couronne « en fer à cheval » <br><strong><span class=\"kw-bio\">Lymphocytes</span> T :</strong> intercalés entre <span class=\"kw-clinique\">les</span> cellules épithélioïdes</td></tr>\n          <tr><td>Couronne périphérique</td><td>Infiltrat lymphocytaire à <strong>prédominance <span class=\"kw-bio\">LT CD4+</span></strong> ; contraste avec la <span class=\"kw-bio\">lymphopénie</span> sanguine responsable de l'<span class=\"kw-bio\">anergie tuberculinique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Nécrose</span></td><td><strong><span class=\"kw-alerte\">Absente</span></strong> — élément distinctif majeur vis-à-vis du granulome tuberculeux</td></tr>\n          <tr><td>Localisation</td><td>Prédominance au <span class=\"kw-clinique\">poumon</span> et aux <span class=\"kw-clinique\">ganglions lymphatiques</span> ; au sein d'un organe, distribution caractéristique de type <span class=\"kw-imagerie\">lymphatique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span></td><td>Résolution sans séquelle dans la majorité des cas ; plus rarement <span class=\"kw-alerte\">fibrose centripète</span> avec distorsion de l'architecture tissulaire (facteur pronostique)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"211-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de la sarcoïdose (âge, sexe de survenue, et prévalence variable selon les ethnies)","contenu":"<p>La <span class=\"kw-def\">sarcoïdose</span> touche l'adulte jeune, avec une répartition très inégale selon <span class=\"kw-clinique\">les</span> zones géographiques et les origines ethniques.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Données épidémiologiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span></td><td><span class=\"kw-chiffre\">30 pour 100 000 habitants</span> environ</td></tr>\n          <tr><td>Âge de début</td><td>Dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2/3</span> des cas <strong>entre <span class=\"kw-chiffre\">20 et 50 ans</span></strong> ; rare avant <span class=\"kw-chiffre\">15 ans</span> ou après <span class=\"kw-chiffre\">75 ans</span> (mais possible à tout âge)</td></tr>\n          <tr><td>Sexe</td><td>Discrète prédominance <strong>féminine</strong> (sex-ratio <span class=\"kw-chiffre\">1 à 1,5 femme pour 1 homme</span>)</td></tr>\n          <tr><td>Gradient géographique</td><td><strong>Gradient nord-sud</strong> de l'<span class=\"kw-def\">incidence</span> : élevée en Europe du Nord (<span class=\"kw-chiffre\">8 à 40 cas/10⁵/an</span>), faible en Europe du Sud et en Amérique latine ; <span class=\"kw-def\">prévalence</span> basse en Asie de l'Est</td></tr>\n          <tr><td>Ethnie</td><td>Plus fréquente dans <span class=\"kw-clinique\">les</span> pays nordiques d'Europe <br>Chez les <strong>Caribéens :</strong> <span class=\"kw-chiffre\">3×</span> plus fréquente et plus sévère <br>Chez les <strong>Afro-américains :</strong> forme plus souvent <span class=\"kw-alerte\">chronique et grave</span></td></tr>\n          <tr><td>Formes familiales</td><td>Retrouvées dans <span class=\"kw-chiffre\">moins de 10 %</span> des cas</td></tr>\n          <tr><td><span class=\"kw-etio\">Tabac</span></td><td>Le <span class=\"kw-etio\">tabac</span> est un <strong>facteur protecteur</strong> de la <span class=\"kw-clinique\">sarcoïdose</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong>À retenir.</strong> Le profil typique = <strong>adulte jeune, plutôt une femme, d'origine nordique ou afro-caribéenne</strong> — l'origine afro-caribéenne <span class=\"kw-def\">annonce</span> une forme plus grave.</div>","frequence":0},{"id":"211-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaitre les mécanismes de la réaction inflammatoire conduisant au granulome","contenu":"<p>La <span class=\"kw-clinique\">sarcoïdose</span> résulte d'une <strong>interaction gène – environnement</strong> : une réaction immunitaire cellulaire spécifique, survenant sur un <span class=\"kw-def\">terrain</span> génétiquement prédisposé, aboutit à l'accumulation de <span class=\"kw-def\">granulomes</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Arguments d'une prédisposition <span class=\"kw-etio\">génétique</span></h4>\n      <ul>\n        <li>Prépondérance <span class=\"kw-etio\">ethnique</span> de la maladie.</li>\n        <li><span class=\"kw-etio\">Formes familiales</span> (<span class=\"kw-chiffre\">&lt; 10 %</span> des cas).</li>\n        <li>Association de certaines formes cliniques à des haplotypes <strong><span class=\"kw-bio\">HLA</span></strong>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Arguments d'une influence environnementale</h4>\n      <ul>\n        <li>Variation <span class=\"kw-etio\">saisonnière</span> de certaines formes (<span class=\"kw-clinique\">syndrome de Löfgren</span>).</li>\n        <li>Atteinte préférentielle des <span class=\"kw-clinique\">organes exposés</span> à l'environnement : œil, poumon, peau.</li>\n        <li>Description de cas <span class=\"kw-etio\">épidémiques</span> — pic d'<span class=\"kw-def\">incidence</span> de <span class=\"kw-clinique\">sarcoïdose</span> multiviscérale chez les <span class=\"kw-etio\">pompiers exposés aux poussières</span> de l'effondrement du World Trade Center.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cascade immunitaire conduisant au granulome</h4>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>1. Exposition antigénique</td><td><span class=\"kw-def\">Contact</span> avec des antigènes environnementaux ou <span class=\"kw-etio\">infectieux</span> : peptides de <span class=\"kw-etio\">mycobactéries</span>, de <span class=\"kw-etio\">propionibactéries</span></td></tr>\n          <tr><td>2. Réponse lymphocytaire</td><td>Réponse à médiation <span class=\"kw-bio\">lymphocytaire T</span>, de profil <strong><span class=\"kw-bio\">Th1 et Th17</span></strong>, avec production locale exagérée d'<span class=\"kw-bio\">INFγ</span>, de <span class=\"kw-bio\">TNFα</span> et d'<span class=\"kw-bio\">IL-2</span></td></tr>\n          <tr><td>3. Activation macrophagique</td><td>Activation des <span class=\"kw-bio\">monocytes-macrophages</span> qui se différencient en cellules épithélioïdes</td></tr>\n          <tr><td>4. Formation du granulome</td><td>Constitution du <span class=\"kw-def\">granulome épithélioïde et giganto-cellulaire</span> ; réaction anormale par sa <span class=\"kw-imagerie\">diffusion</span> et sa persistance</td></tr>\n          <tr><td>5. Anergie immunitaire</td><td><span class=\"kw-bio\">Anergie</span> du système immunitaire avec hyperactivité des <span class=\"kw-bio\">LT régulateurs</span> — explique l'<span class=\"kw-bio\">anergie tuberculinique</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Composition du granulome sarcoïdien</h4>\n      <table >\n        <thead><tr><th>Zone</th><th>Constituants</th></tr></thead>\n        <tbody>\n          <tr><td>Follicule central</td><td><strong>Cellules épithélioïdes :</strong> macrophages d'aspect épithélial <br><strong>Cellules géantes de Langhans :</strong> cellules multinucléées (fusion de cellules épithélioïdes), noyaux en couronne « en fer à cheval » <br><strong><span class=\"kw-bio\">Lymphocytes</span> T :</strong> intercalés dans le follicule</td></tr>\n          <tr><td>Couronne</td><td>Infiltrat lymphocytaire à <strong>prédominance <span class=\"kw-bio\">LT CD4+</span></strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Nécrose</span></td><td><strong><span class=\"kw-alerte\">Pas de nécrose caséeuse</span></strong> — contrairement au granulome tuberculeux</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong>À retenir.</strong> Une réaction tuberculoïde identique au granulome sarcoïdien s'observe en réponse à des particules minérales jouant le rôle d'haptènes (<span class=\"kw-etio\">béryllium</span>) : c'est la <span class=\"kw-def\">bérylliose</span>, principal <span class=\"kw-def\">diagnostic différentiel</span> histologique.</div>","frequence":5},{"id":"211-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères du diagnostic d’une sarcoïdose","contenu":"<p>Le diagnostic de <span class=\"kw-clinique\">sarcoïdose</span> repose sur un <strong>triptyque</strong> indissociable — aucun de ces critères n'est suffisant isolément.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>1. Tableau clinico-radiologique</td><td>Présentation <strong>compatible</strong> avec une <span class=\"kw-clinique\">sarcoïdose</span></td></tr>\n          <tr><td>2. Preuve histologique</td><td>Mise en évidence de <strong><span class=\"kw-def\">granulomes épithélioïdes et giganto-cellulaires sans nécrose caséeuse</span></strong></td></tr>\n          <tr><td>3. Exclusion</td><td><strong>Élimination des autres granulomatoses</strong> (infectieuses, médicamenteuses, néoplasiques)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Stratégie hiérarchisée des prélèvements</h4>\n      <p><span class=\"kw-clinique\">Les</span> sites de <span class=\"kw-bio\">biopsie</span> sont choisis selon leur <strong>caractère peu invasif</strong>, leur rentabilité diagnostique et les organes atteints.</p>\n      <table >\n        <thead><tr><th>Intention</th><th>Sites de prélèvement</th></tr></thead>\n        <tbody>\n          <tr><td>1ʳᵉ intention (peu invasif)</td><td><span class=\"kw-clinique\">Lésion cutanée</span> (sauf <span class=\"kw-clinique\">érythème</span> noueux), cicatrice indurée, <span class=\"kw-clinique\">nodule</span> conjonctival <br><span class=\"kw-clinique\">Adénopathie périphérique</span>, <strong>glande salivaire accessoire</strong> (rentabilité ≈ <span class=\"kw-chiffre\">40 %</span>), glande lacrymale <br><span class=\"kw-ttt\">Ponction</span> écho-guidée des <span class=\"kw-clinique\">ganglions médiastinaux</span></td></tr>\n          <tr><td>2ᵉ intention</td><td><span class=\"kw-clinique\">Endoscopie bronchique</span> avec <span class=\"kw-bio\">biopsies</span> bronchiques étagées et <span class=\"kw-bio\">LBA</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-bio\">lavage broncho-alvéolaire</span> montre typiquement une <strong><span class=\"kw-bio\">alvéolite lymphocytaire</span></strong> avec un <strong>rapport <span class=\"kw-bio\">CD4/CD8 &gt; 3,5</span></strong>.</p>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège.</strong> Toute pièce histologique doit faire l'objet de <span class=\"kw-bio\">colorations spéciales (Ziehl)</span> et d'une <span class=\"kw-bio\">culture sur milieu de Löwenstein</span> afin d'éliminer formellement une <span class=\"kw-etio\">tuberculose</span> avant de retenir le diagnostic.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":5},{"id":"211-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les formes fréquentes de la sarcoïdose : les atteintes respiratoires, le syndrome de Löfgren et l'érythème noueux","contenu":"<p>Trois présentations dominent le tableau clinique de la <span class=\"kw-clinique\">sarcoïdose</span> : l'<strong>atteinte médiastino-pulmonaire</strong>, le <strong><span class=\"kw-clinique\">syndrome de Löfgren</span></strong> et l'<strong><span class=\"kw-clinique\">érythème</span> noueux</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1 · Atteinte médiastino-pulmonaire — la plus fréquente</h4>\n      <p>Présente chez <strong><span class=\"kw-chiffre\">90 %</span></strong> des patients (isolée dans <span class=\"kw-chiffre\">50 %</span> des cas). Elle se caractérise par un <strong>contraste entre la pauvreté clinique et la richesse radiologique</strong>.</p>\n      <ul>\n        <li>Signes fonctionnels discrets : <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">toux non productive</span> (fréquente), <span class=\"kw-clinique\">dyspnée</span> (tardive, formes avancées), <span class=\"kw-clinique\">douleurs thoraciques</span>.</li>\n        <li>Examen physique pauvre : <span class=\"kw-clinique\">hippocratisme digital</span>, auscultation le plus souvent normale, rares <span class=\"kw-clinique\">crépitants des bases</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span> radiologique</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Stade</span> 0 (<span class=\"kw-chiffre\">10-20 %</span>)</td><td><span class=\"kw-imagerie\">RXT normale</span> — formes extra-thoraciques pures</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> I (<span class=\"kw-chiffre\">50 %</span>)</td><td><span class=\"kw-imagerie\">Adénopathies hiliaires bilatérales et médiastinales</span>, sans atteinte parenchymateuse — bilatérales, symétriques, non compressives</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> II</td><td><span class=\"kw-clinique\">Adénopathies</span> <strong>+</strong> <span class=\"kw-imagerie\">atteinte parenchymateuse pulmonaire</span></td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> III (<span class=\"kw-chiffre\">25 %</span>)</td><td><span class=\"kw-imagerie\">Atteinte parenchymateuse isolée</span> (sans <span class=\"kw-clinique\">adénopathie</span>) — micronodules diffus</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> IV (<span class=\"kw-chiffre\">5-8 %</span>)</td><td><span class=\"kw-alerte\">Fibrose pulmonaire</span> — opacités rétractiles, distorsion, ascension des hiles</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2 · <span class=\"kw-clinique\">Syndrome de Löfgren</span> — forme aiguë de bon <span class=\"kw-def\">pronostic</span></h4>\n      <p>Forme <strong>aiguë et <span class=\"kw-etio\">inflammatoire</span></strong> de <span class=\"kw-clinique\">sarcoïdose</span>, touchant surtout la <strong>femme européenne</strong>. Moyen mnémotechnique : <strong>FANTA</strong>.</p>\n      <table >\n        <thead><tr><th>FANTA</th><th>Signe</th></tr></thead>\n        <tbody>\n          <tr><td>F</td><td><span class=\"kw-clinique\">Fièvre</span> (rare dans la <span class=\"kw-clinique\">sarcoïdose</span> en dehors du <span class=\"kw-clinique\">syndrome de Löfgren</span>)</td></tr>\n          <tr><td>A</td><td><span class=\"kw-clinique\">Arthralgies / arthrites des chevilles</span> — atteinte bilatérale quasi constante</td></tr>\n          <tr><td>N</td><td><span class=\"kw-clinique\">érythème Noueux</span></td></tr>\n          <tr><td>T</td><td><span class=\"kw-bio\">anergie Tuberculinique</span></td></tr>\n          <tr><td>A</td><td><span class=\"kw-imagerie\">Adénopathies hiliaires bilatérales</span> et médiastinales</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong>À retenir.</strong> Le <span class=\"kw-def\">pronostic</span> du <span class=\"kw-clinique\">syndrome de Löfgren</span> est <strong>excellent</strong> : <span class=\"kw-clinique\">évolution</span> spontanément résolutive dans <span class=\"kw-chiffre\">90 %</span> des cas en <span class=\"kw-chiffre\">moins de 2 ans</span>.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">3 · <span class=\"kw-clinique\">Érythème</span> noueux</h4>\n      <p>Manifestation cutanée <strong>non spécifique</strong> : la <span class=\"kw-clinique\">sarcoïdose</span> en est la <strong><span class=\"kw-etio\">1ʳᵉ cause en France</span></strong> (selon le CEP). Il se présente sous forme de <span class=\"kw-clinique\">nouures</span> (nodules hypodermiques) des faces d'extension des jambes, en régions prétibiales.</p>\n      <ul>\n        <li>Apparition aiguë, lésions bilatérales, fermes, douloureuses, chaudes.</li>\n        <li><span class=\"kw-clinique\">Évolution</span> biphasique des couleurs en <span class=\"kw-chiffre\">2-3 semaines</span> : bleu-violet → vert-jaune → brun.</li>\n        <li><strong><span class=\"kw-ci\">Biopsie cutanée non nécessaire</span></strong> : le diagnostic d'<span class=\"kw-clinique\">érythème</span> noueux est clinique.</li>\n      </ul>\n      <div class=\"callout callout-danger\">⚠️ <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> L'<span class=\"kw-alerte\">atteinte cardiaque</span> de la <span class=\"kw-clinique\">sarcoïdose</span> (troubles de conduction, troubles du rythme) est une <strong>indication formelle</strong> à une <span class=\"kw-ttt\">corticothérapie à forte dose</span> associée à un <span class=\"kw-ttt\">traitement immunosuppresseur</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 282 — <span class=\"kw-def\">MICI</span></em></p>","frequence":12},{"id":"211-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales manifestations extra-respiratoires","contenu":"<p>La <span class=\"kw-clinique\">sarcoïdose</span> est une maladie systémique : tout organe peut être atteint. Tableau des principales atteintes extra-respiratoires (avec leur fréquence) et de leurs explorations.</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Manifestations et explorations</th></tr></thead>\n        <tbody>\n          <tr><td>Signes généraux</td><td><strong>Manif :</strong> <span class=\"kw-clinique\">asthénie</span> importante (très fréquente) ; <span class=\"kw-clinique\">amaigrissement</span> ; <span class=\"kw-clinique\">fièvre</span> rare (Löfgren, Heerfordt, atteinte hépatique ou rénale)</td></tr>\n          <tr><td>Œil (<span class=\"kw-chiffre\">15-30 %</span>)</td><td><strong>Manif :</strong> <span class=\"kw-clinique\">uvéite antérieure aiguë</span> (œil rouge, BAV) ; uvéite postérieure ; synéchies, cataracte, glaucome <br><strong>Explorations :</strong> lampe à fente ; <span class=\"kw-imagerie\">angiographie</span> rétinienne</td></tr>\n          <tr><td>Peau (<span class=\"kw-chiffre\">15-30 %</span>)</td><td><strong>Manif :</strong> sarcoïdes à nodules ou en plaques ; <span class=\"kw-alerte\">lupus pernio</span> (forme chronique potentiellement destructrice) ; <span class=\"kw-clinique\">érythème</span> noueux <br><strong>Explorations :</strong> <span class=\"kw-bio\">biopsie</span> cutanée (sauf érythème noueux)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Adénopathies</span> (<span class=\"kw-chiffre\">15 %</span>)</td><td><strong>Manif :</strong> <span class=\"kw-clinique\">adénopathies</span> superficielles cervicales, sus-claviculaires, axillaires, <strong><span class=\"kw-clinique\">épitrochléennes</span></strong> (valeur sémiologique forte) <br><strong>Explorations :</strong> <span class=\"kw-imagerie\">échographie</span> ; <span class=\"kw-bio\">biopsie</span> ganglionnaire</td></tr>\n          <tr><td>Foie – Rate (<span class=\"kw-chiffre\">15 %</span>)</td><td><strong>Manif :</strong> <span class=\"kw-bio\">cholestase</span> non ictérique, cytolyse ; <span class=\"kw-clinique\">hépatomégalie</span>, splénomégalie <br><strong>Explorations :</strong> <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-imagerie\">échographie</span> ; <span class=\"kw-bio\">biopsie</span> hépatique</td></tr>\n          <tr><td>Système nerveux (<span class=\"kw-chiffre\">5-10 %</span>)</td><td><strong>Manif :</strong> <span class=\"kw-clinique\">méningite lymphocytaire</span> ; <span class=\"kw-clinique\">diabète insipide</span> (granulome hypophysaire) ; atteinte des nerfs crâniens (<span class=\"kw-clinique\">paralysie faciale périphérique</span>, V1) <br><strong>Explorations :</strong> <span class=\"kw-bio\">ponction lombaire</span> ; <span class=\"kw-imagerie\">IRM</span> ; dosages hormonaux</td></tr>\n          <tr><td>ORL (<span class=\"kw-chiffre\">2-5 %</span>)</td><td><strong>Manif :</strong> obstruction nasale, dysphonie ; <strong><span class=\"kw-clinique\">syndrome de Heerfordt</span></strong> = uvéo-parotidite fébrile + PFP + <span class=\"kw-def\">méningite</span> lymphocytaire <br><strong>Explorations :</strong> examen ORL ; <span class=\"kw-imagerie\">TDM</span> des sinus</td></tr>\n          <tr><td>Ostéo-articulaire (<span class=\"kw-chiffre\">&lt; 5 %</span>)</td><td><strong>Manif :</strong> <span class=\"kw-clinique\">arthralgies</span> / arthrites ; <span class=\"kw-clinique\">dactylite</span> de la main ; atteinte unguéale associée <br><strong>Explorations :</strong> <span class=\"kw-imagerie\">radiographie</span> ; <span class=\"kw-bio\">biopsie</span> osseuse</td></tr>\n          <tr><td>Cœur (<span class=\"kw-chiffre\">&lt; 5 %</span>)</td><td><strong>Manif :</strong> <span class=\"kw-alerte\">2ᵉ cause de mortalité</span> de la <span class=\"kw-clinique\">sarcoïdose</span> ; troubles de conduction (BAV, BBD), troubles du rythme (<span class=\"kw-alerte\">TV</span>, FV) ; <span class=\"kw-ttt\">corticothérapie + immunosuppresseur</span> indiqués <br><strong>Explorations :</strong> <span class=\"kw-bio\">ECG</span>, <span class=\"kw-imagerie\">Holter</span> ; <span class=\"kw-imagerie\">ETT</span>, <span class=\"kw-imagerie\">IRM</span> cardiaque, <span class=\"kw-imagerie\">TEP</span></td></tr>\n          <tr><td>Rein (<span class=\"kw-chiffre\">&lt; 2 %</span>)</td><td><strong>Manif :</strong> <span class=\"kw-bio\">néphrocalcinose</span>, néphropathie interstitielle granulomateuse ; <span class=\"kw-bio\">hypercalcémie</span>, hypercalciurie <br><strong>Explorations :</strong> calciurie ; <span class=\"kw-imagerie\">échographie</span> rénale ; <span class=\"kw-bio\">biopsie</span> rénale</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — Altération chronique de la vision · 151 — <span class=\"kw-def\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 232 — <span class=\"kw-def\">Fibrillation atriale</span> · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 268 — Hypercalcémie</em></p>","frequence":1},{"id":"211-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques nécessitant de chercher des diagnostics différentiels","contenu":"<p>Certains éléments cliniques, radiologiques ou biologiques doivent faire <strong>douter du diagnostic de <span class=\"kw-clinique\">sarcoïdose</span></strong> et conduire à rechercher activement un <span class=\"kw-def\">diagnostic différentiel</span>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Signes devant alerter</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Âge de début <strong>&lt;<span class=\"kw-chiffre\"> 20 ans</span> ou &gt;<span class=\"kw-chiffre\"> 50 ans</span></strong></td></tr>\n          <tr><td>Clinique</td><td><span class=\"kw-clinique\">Signes généraux</span> (en dehors du <span class=\"kw-clinique\">syndrome de Löfgren</span>) <br><span class=\"kw-clinique\">Râles crépitants</span> (l'auscultation est habituellement pauvre dans la <span class=\"kw-clinique\">sarcoïdose</span>) <br><span class=\"kw-clinique\">Hippocratisme digital</span></td></tr>\n          <tr><td>Imagerie</td><td><span class=\"kw-imagerie\">Micronodules de distribution non lymphatique</span> au <span class=\"kw-imagerie\">scanner</span> <br><span class=\"kw-clinique\">Adénopathies</span> médiastinales <span class=\"kw-imagerie\">compressives ou asymétriques</span> <br><span class=\"kw-imagerie\">Radiographie thoracique normale</span></td></tr>\n          <tr><td>Biologie</td><td><span class=\"kw-bio\">Intradermoréaction à la tuberculine positive</span> <br><span class=\"kw-bio\">Hypogammaglobulinémie</span> <br><span class=\"kw-bio\">Sérologie VIH positive</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Devant ces signes, « ce n'est probablement pas une <span class=\"kw-clinique\">sarcoïdose</span> » : évoquer une <span class=\"kw-etio\">tuberculose</span>, un <span class=\"kw-etio\">lymphome</span>, un <span class=\"kw-etio\">déficit immunitaire commun variable</span> ou une autre granulomatose avant de conclure.</div>","frequence":1},{"id":"211-8","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un exemple typique d’érythème noueux","contenu":"<p>L'<span class=\"kw-clinique\">érythème noueux</span> est la manifestation cutanée révélatrice la plus emblématique de la <span class=\"kw-clinique\">sarcoïdose</span>, notamment dans le cadre du <strong><span class=\"kw-clinique\">syndrome de Löfgren</span></strong>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/211/erytheme-noueux.png\" alt=\"Syndrome de Löfgren : radiographie thoracique avec adénopathies hilaires bilatérales, polyarthrite aiguë des chevilles et érythème noueux des faces antérieures de jambes\" style=\"max-width:600px;width:100%;height:auto;border-radius:6px;display:block;\">\n        <figcaption><em>Syndrome de Löfgren — le panneau de droite illustre un <strong><span class=\"kw-clinique\">érythème</span> noueux</strong> typique des régions prétibiales. Il s'associe ici à des <span class=\"kw-clinique\">adénopathies</span> hilaires bilatérales (<span class=\"kw-imagerie\">radiographie thoracique</span>) et à une polyarthrite aiguë des chevilles.</em></figcaption>\n      </figure>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie de l'<span class=\"kw-clinique\">érythème</span> noueux</h4>\n      <ul>\n        <li><strong>Nouures</strong> = nodules hypodermiques (sous-cutanés), d'apparition <span class=\"kw-clinique\">aiguë</span>.</li>\n        <li>Lésions <span class=\"kw-clinique\">bilatérales</span>, fermes, non fluctuantes, en relief.</li>\n        <li>Topographie : faces d'extension des membres inférieurs — <strong>régions prétibiales et genoux</strong>.</li>\n        <li><span class=\"kw-clinique\">Douloureuses</span>, chaudes, adhérentes aux plans superficiel et profond.</li>\n        <li><span class=\"kw-clinique\">Évolution</span> <strong>biphasique des couleurs</strong> en <span class=\"kw-chiffre\">2 à 3 semaines</span> : bleu-violet → vert-jaune → brun.</li>\n      </ul>\n      <div class=\"callout callout-info\">📌 <strong>À retenir.</strong> Le diagnostic d'<span class=\"kw-clinique\">érythème</span> noueux est <strong><span class=\"kw-ci\">clinique</span></strong> : la <span class=\"kw-ci\">biopsie cutanée n'est pas nécessaire</span> (<span class=\"kw-clinique\">lésion</span> non spécifique). La prise en charge est <span class=\"kw-ttt\">symptomatique</span> : repos, contention élastique, <span class=\"kw-ttt\">AINS</span> ou <span class=\"kw-ttt\">colchicine</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Mémo étiologique — SYSTEME BLIC</h4>\n      <ul>\n        <li><strong>S</strong> — <span class=\"kw-etio\">Sarcoïdose</span> (inaugurale dans <span class=\"kw-chiffre\">20 %</span> des cas, 1ʳᵉ cause en France selon le CEP)</li>\n        <li><strong>Y</strong> — <span class=\"kw-etio\">Yersiniose</span></li>\n        <li><strong>S</strong> — <span class=\"kw-etio\">Streptocoque</span> β-hémolytique du groupe A</li>\n        <li><strong>T</strong> — <span class=\"kw-etio\">Tuberculose</span></li>\n        <li><strong>E</strong> — Enceinte (<span class=\"kw-ci\">grossesse</span>)</li>\n        <li><strong>M</strong> — Médicaments</li>\n        <li><strong>E</strong> — <span class=\"kw-etio\">Entérocolopathie</span> (<span class=\"kw-def\">maladie de Crohn</span>, <span class=\"kw-def\">RCH</span>)</li>\n        <li><strong>B</strong> — <span class=\"kw-etio\">Behçet</span></li>\n        <li><strong>L</strong> — <span class=\"kw-etio\">Lèpre</span></li>\n        <li><strong>I</strong> — Idiopathique (≈<span class=\"kw-chiffre\"> 50 %</span> des cas)</li>\n        <li><strong>C</strong> — Cancer, <span class=\"kw-clinique\">Chlamydia</span></li>\n      </ul>","frequence":5},{"id":"211-9","rang":"B","rubrique":"Étiologies","titre":"Connaitre les principales causes de granulomatoses secondaires","contenu":"<p>De nombreuses affections produisent des granulomes épithélioïdes et g<span class=\"kw-chiffre\">iga</span>ntocellulaires : leur image histologique est <strong>insuffisante</strong> pour porter à elle seule le diagnostic de <span class=\"kw-clinique\">sarcoïdose</span>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Causes de granulomatose secondaire</th></tr></thead>\n        <tbody>\n          <tr><td>Infections</td><td><span class=\"kw-etio\">Tuberculose</span>, mycobactéries non tuberculeuses, maladie de Whipple, brucellose, <span class=\"kw-clinique\">fièvre</span> Q, <span class=\"kw-clinique\">syphilis</span>, lèpre ; mycoses (histoplasmose, cryptococcose) ; leishmaniose</td></tr>\n          <tr><td>Médicaments</td><td>Granulomatose « sarcoid-like » induite par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">inhibiteurs de checkpoint immunitaire (anti-PD1, anti-PDL1)</span>, l'<span class=\"kw-ttt\">interféron</span>, les <span class=\"kw-ttt\">anti-TNF</span>, le <span class=\"kw-ttt\">BCG intra-vésical</span> ; <span class=\"kw-etio\">syndrome de reconstitution immunitaire (IRIS)</span> chez le patient <span class=\"kw-etio\">VIH</span></td></tr>\n          <tr><td>Maladies inflammatoires</td><td><span class=\"kw-etio\">MICI</span> (<span class=\"kw-def\">maladie de Crohn</span> ++), <span class=\"kw-def\">cirrhose</span> biliaire primitive, <span class=\"kw-ttt\">sclérose</span> en plaques ; <span class=\"kw-etio\">granulomatose avec polyangéite</span> (<span class=\"kw-clinique\">Wegener</span>), GEPA ; rosacée, <span class=\"kw-etio\">granulome annulaire</span></td></tr>\n          <tr><td>Néoplasies</td><td>Réactions granulomateuses <strong>péri-tumorales</strong> : <span class=\"kw-etio\">lymphomes</span>, chorion de certains carcinomes</td></tr>\n          <tr><td>Autres</td><td>Maladies par exposition particulaire : <span class=\"kw-etio\">bérylliose</span>, talcose, silicose ; <span class=\"kw-etio\">déficit immunitaire commun variable</span> ; pneumopathies d'<span class=\"kw-ci\">hypersensibilité</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 169 — <span class=\"kw-etio\">VIH</span> · 193 — <span class=\"kw-def\">Vascularite</span> systémique · 282 — <span class=\"kw-def\">MICI</span></em></p>","frequence":1},{"id":"211-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt et les limites des principaux tests biologiques","contenu":"<p>Aucun examen <span class=\"kw-ttt\">biologique</span> n'est spécifique de la <span class=\"kw-clinique\">sarcoïdose</span>. Le bilan systématique recherche un retentissement et des anomalies évocatrices.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Anomalies attendues / intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS</span>-<span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">CRP</span></td><td><span class=\"kw-bio\">Lymphopénie</span> prédominant sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">LT CD4+</span> (sans sur-risque <span class=\"kw-etio\">infectieux</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">Ionogramme</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">EPS</span></td><td>Retentissement rénal ; <span class=\"kw-bio\">hypergammaglobulinémie polyclonale</span> à l'électrophorèse (activation des LB)</td></tr>\n          <tr><td><span class=\"kw-bio\">Calcémie</span> + calciurie des <span class=\"kw-chiffre\">24 h</span></td><td><span class=\"kw-bio\">Hypercalciurie</span> fréquente (≈ <span class=\"kw-chiffre\">35 %</span>) ; <span class=\"kw-bio\">hypercalcémie</span> (<span class=\"kw-chiffre\">5-10 %</span>), favorisée par l'<span class=\"kw-ci\">exposition solaire</span>. Mécanisme : <span class=\"kw-clinique\">les</span> macrophages sarcoïdiens sécrètent la 1α-hydroxylase, produisant du calcitriol qui augmente l'absorption intestinale du calcium</td></tr>\n          <tr><td>Enzyme de conversion de l'angiotensine (ECA)</td><td>Produite par <span class=\"kw-clinique\">les</span> macrophages activés : <strong>peu sensible</strong> (élevée dans <span class=\"kw-chiffre\">60 %</span> des cas), <strong>non spécifique</strong> ; reflète la <span class=\"kw-clinique\">masse</span> granulomateuse mais <span class=\"kw-alerte\">sans valeur pronostique</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span>, VHC + <span class=\"kw-clinique\">IDR</span> à la tuberculine</td><td><span class=\"kw-clinique\">IDR</span> négative dans <span class=\"kw-chiffre\">80 %</span> des cas (<strong><span class=\"kw-bio\">anergie tuberculinique</span></strong>) ; une <span class=\"kw-bio\">négativation</span> de l'IDR a une réelle valeur diagnostique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège.</strong> L'<span class=\"kw-bio\">ECA</span> est <span class=\"kw-ci\">ininterprétable chez les patients sous IEC</span> : ces médicaments abaissent artificiellement son taux sérique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie</em></p>","frequence":2},{"id":"211-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d'imagerie devant une sarcoïdose","contenu":"<p>La <strong><span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span> de face et de profil</strong> est l'examen de base : elle permet la <span class=\"kw-def\">classification</span> en <strong>5 stades</strong> de valeur pronostique (probabilité de guérison spontanée).</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span> (sur <span class=\"kw-imagerie\">RXT</span>)</th><th>Description radiologique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Stade</span> 0 (<span class=\"kw-chiffre\">10-20 %</span>)</td><td><span class=\"kw-imagerie\">RXT normale</span></td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> I (<span class=\"kw-chiffre\">50 %</span>)</td><td><span class=\"kw-imagerie\">Adénopathies hiliaires bilatérales et médiastinales</span> ; bilatérales, symétriques, non compressives — peuvent se calcifier dans <span class=\"kw-clinique\">les</span> formes prolongées</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> II</td><td><span class=\"kw-clinique\">Adénopathies</span> <strong>+</strong> <span class=\"kw-imagerie\">atteinte parenchymateuse</span></td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> III (<span class=\"kw-chiffre\">25 %</span>)</td><td><span class=\"kw-imagerie\">Atteinte parenchymateuse isolée</span> : micronodules diffus des parties supérieures et moyennes</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> IV (<span class=\"kw-chiffre\">5-8 %</span>)</td><td><span class=\"kw-alerte\">Fibrose pulmonaire</span> apicale et postérieure : distorsion broncho-vasculaire, ascension des hiles, emphysème para-cicatriciel, déformation « en tente » des coupoles ; risque de <span class=\"kw-alerte\">greffe aspergillaire</span> (image en grelot)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-imagerie\">TDM</span> thoracique haute résolution (<span class=\"kw-imagerie\">TDM</span>-HR)</h4>\n      <p>Plus sensible que la <span class=\"kw-imagerie\">RXT</span>, elle ne <strong><span class=\"kw-alerte\">modifie pas la classification en stades</span></strong>, qui reste fondée sur la seule <span class=\"kw-imagerie\">RXT</span>.</p>\n      <ul>\n        <li><strong>Topographie :</strong> <span class=\"kw-imagerie\">distribution lymphatique</span> — axes péri-broncho-vasculaires, régions sous-pleurales, le long des scissures.</li>\n        <li><strong>Sémiologie :</strong> <span class=\"kw-imagerie\">micronodules diffus</span> ; <span class=\"kw-imagerie\">réticulations septales à grandes mailles</span> ; signes débutants de fibrose (bronchectasies par traction, rayon de miel apical).</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-imagerie\">TEP</span>-<span class=\"kw-imagerie\">scanner</span> au 18-FDG</h4>\n      <p>Non réalisée en routine (irradiante, coûteuse). Indications ciblées : suspicion d'<span class=\"kw-alerte\">atteinte cardiaque active</span>, recherche d'un site occulte à biopsier, <span class=\"kw-clinique\">asthénie</span> importante inexpliquée, évaluation de l'activité d'un <span class=\"kw-def\">stade</span> IV.</p>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège.</strong> La <span class=\"kw-imagerie\">TDM</span>-HR illustre mieux <span class=\"kw-clinique\">les</span> lésions et leur distribution, mais la <span class=\"kw-alerte\">classification en stades repose sur la seule RXT</span> — <span class=\"kw-ci\">ne jamais</span> « reclasser » un patient sur le <span class=\"kw-imagerie\">scanner</span>.</div>","frequence":4},{"id":"211-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la place de l’anatomie pathologique pour le diagnostic et la stratégie des prélèvements","contenu":"<p>La preuve histologique est en règle nécessaire — mais pas toujours indispensable. La stratégie de prélèvement est hiérarchisée du <strong>moins invasif</strong> au plus invasif.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Situations où la <span class=\"kw-bio\">biopsie</span> n'est pas indispensable</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Syndrome de Löfgren</span>, <span class=\"kw-clinique\">syndrome de Heerfordt</span> ou <span class=\"kw-clinique\">lupus pernio</span> associés à des <span class=\"kw-imagerie\">adénopathies médiastino-hiliaires bilatérales typiques</span> (caractère très évocateur).</li>\n        <li><span class=\"kw-imagerie\">Stade I asymptomatique</span>, sous couvert d'une <span class=\"kw-def\">surveillance</span> spécialisée.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Hiérarchie des sites de prélèvement</h4>\n      <table >\n        <thead><tr><th>Intention</th><th>Sites</th></tr></thead>\n        <tbody>\n          <tr><td>1ʳᵉ intention (peu invasif)</td><td><span class=\"kw-clinique\">Lésion cutanée</span> (sauf <span class=\"kw-clinique\">érythème</span> noueux), cicatrice indurée, <span class=\"kw-clinique\">nodule</span> conjonctival ; <span class=\"kw-clinique\">adénopathie périphérique</span> ; <strong>glande salivaire accessoire</strong> (rentabilité ≈ <span class=\"kw-chiffre\">40 %</span>) ; <span class=\"kw-ttt\">ponction</span> écho-guidée des ganglions médiastinaux</td></tr>\n          <tr><td>2ᵉ intention</td><td><span class=\"kw-clinique\">Endoscopie bronchique</span> : muqueuse normale ou « en <span class=\"kw-imagerie\">fond d'œil</span> » ; <span class=\"kw-bio\">biopsies</span> bronchiques étagées (sensibilité <span class=\"kw-chiffre\">50-60 %</span>) ; <span class=\"kw-bio\">LBA</span> = alvéolite lymphocytaire <span class=\"kw-chiffre\">CD4</span>+, rapport <span class=\"kw-bio\">CD4/CD8 &gt; 3,5</span></td></tr>\n          <tr><td>Dernière intention</td><td><span class=\"kw-bio\">Biopsie</span> pulmonaire trans-bronchique (risque d'<span class=\"kw-alerte\">hémorragie</span> ou de <span class=\"kw-alerte\">pneumothorax</span>) ; <span class=\"kw-bio\">biopsie</span> hépatique ; <span class=\"kw-clinique\">médiastinoscopie</span> (sensibilité <span class=\"kw-chiffre\">100 %</span>, très rarement réalisée)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>À retenir.</strong> Toute <span class=\"kw-bio\">biopsie</span> impose des <span class=\"kw-bio\">colorations de Ziehl</span> et une <span class=\"kw-bio\">culture sur milieu de Löwenstein</span> pour éliminer une <span class=\"kw-etio\">tuberculose</span>.</div>","frequence":1},{"id":"211-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les anomalies explorations fonctionnelles respiratoires typiques","contenu":"<p><span class=\"kw-clinique\">Les</span> explorations fonctionnelles respiratoires (<span class=\"kw-bio\">EFR</span>) précisent le retentissement pulmonaire et participent à l'évaluation pronostique.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Anomalies typiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Spirométrie</span></td><td>Normale au <span class=\"kw-def\">stade</span> I ; <strong><span class=\"kw-bio\">trouble ventilatoire restrictif</span></strong> (≈ <span class=\"kw-chiffre\">65 %</span>), parfois mixte ; <span class=\"kw-alerte\">trouble ventilatoire obstructif isolé</span> rare = facteur de mauvais <span class=\"kw-def\">pronostic</span></td></tr>\n          <tr><td><span class=\"kw-bio\">DLCO</span> (<span class=\"kw-imagerie\">diffusion</span> alvéolo-capillaire)</td><td><strong><span class=\"kw-bio\">Diminution précoce</span></strong> de la <span class=\"kw-bio\">DLCO</span>, <strong>avant</strong> l'altération des volumes pulmonaires</td></tr>\n          <tr><td><span class=\"kw-bio\">Gaz du sang</span></td><td>Longtemps <span class=\"kw-bio\">normaux au repos</span></td></tr>\n          <tr><td>Test de marche de <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>6</span> min</span>utes</td><td><span class=\"kw-ttt\">Réduction</span> de la distance, <span class=\"kw-clinique\">désaturation à l'effort</span> — peut refléter une <span class=\"kw-alerte\">hypertension pulmonaire</span> ou une <span class=\"kw-alerte\">insuffisance respiratoire</span></td></tr>\n          <tr><td>Épreuve cardio-pulmonaire d'exercice</td><td>Utile en cas de <span class=\"kw-clinique\">dyspnée inexpliquée</span> pour préciser le mécanisme (cardiaque, parenchymateux ou musculaire)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>À retenir.</strong> La <span class=\"kw-bio\">DLCO</span> chute <strong>avant</strong> <span class=\"kw-clinique\">les</span> volumes pulmonaires : c'est le <span class=\"kw-bio\">signe fonctionnel le plus précoce</span> de l'atteinte parenchymateuse.</div>","frequence":1}],"astuces":[],"strategie":{"redflags":"<ul><li><span class=\"kw-alerte\">Atteinte cardiaque</span> — <span class=\"kw-alerte\">2ᵉ cause de mortalité</span> : troubles de <span class=\"kw-clinique\">conduction</span> (<span class=\"kw-clinique\">BAV</span>, <span class=\"kw-clinique\">BBD</span>), troubles du <span class=\"kw-clinique\">rythme</span> (<span class=\"kw-clinique\">TV</span>, <span class=\"kw-clinique\">FV</span>), <span class=\"kw-alerte\">mort subite</span></li><li><span class=\"kw-alerte\">Neurosarcoïdose</span> : <span class=\"kw-clinique\">méningite lymphocytaire</span>, <span class=\"kw-clinique\">diabète insipide</span>, <span class=\"kw-clinique\">paralysie faciale périphérique</span> — <span class=\"kw-alerte\">pronostic vital</span></li><li><span class=\"kw-alerte\">Hypercalcémie sévère</span>, favorisée par l'<span class=\"kw-ci\">exposition solaire</span></li><li><span class=\"kw-alerte\">Uvéite postérieure / chronique</span> : risque de <span class=\"kw-clinique\">cécité</span> (<span class=\"kw-def\">pronostic</span> visuel)</li><li><span class=\"kw-alerte\">Lupus pernio</span> : forme cutanée <span class=\"kw-alerte\">destructrice</span> (destruction <span class=\"kw-clinique\">osseuse et cartilagineuse</span> ORL)</li><li><span class=\"kw-alerte\">Fibrose pulmonaire</span> (<span class=\"kw-def\">stade</span> IV) : <span class=\"kw-alerte\">insuffisance respiratoire chronique</span>, <span class=\"kw-alerte\">HTAP du groupe 5</span>, <span class=\"kw-alerte\">greffe aspergillaire</span></li></ul>","principes":"<p>La <strong>majorité des sarcoïdoses ne nécessitent aucun traitement</strong> : <span class=\"kw-def\">surveillance simple</span> (résolution spontanée dans <span class=\"kw-chiffre\">50 %</span> des cas en <span class=\"kw-chiffre\">&lt; 2 ans</span>). Le traitement est réservé aux atteintes <span class=\"kw-alerte\">graves</span>, menaçantes ou gênantes.</p><p><strong>Abstention + <span class=\"kw-def\">surveillance</span> <span class=\"q\">— formes bénignes</span></strong></p><ul><li><span class=\"kw-def\">Stade I asymptomatique</span> · <span class=\"kw-def\">syndrome de Löfgren</span></li><li>Résolution spontanée dans <span class=\"kw-chiffre\">90 %</span> des cas en <span class=\"kw-chiffre\">&lt; 2 ans</span></li></ul><p><strong><span class=\"kw-clinique\">Érythème</span> noueux <span class=\"q\">— symptomatique</span></strong></p><ul><li><span class=\"kw-ttt\">Repos</span> · <span class=\"kw-ttt\">contention élastique</span></li><li><span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">colchicine</span>, <span class=\"kw-ttt\">antipaludéens de synthèse</span></li></ul><p><strong>Atteintes graves <span class=\"q\">— cœur, SNC, hypercalcémie, œil, rein</span></strong></p><p>Hypercalcémie : éviter l'<span class=\"kw-ci\">exposition solaire</span> et la <span class=\"kw-ci\">majoration des apports calciques</span></p><ul><li><span class=\"kw-ttt\">Corticothérapie générale</span> (à <span class=\"kw-chiffre\">forte dose</span> pour le cœur)</li><li>Indication formelle d'un <span class=\"kw-ttt\">immunosuppresseur</span> associé pour l'<span class=\"kw-alerte\">atteinte cardiaque</span></li></ul><p><strong>Atteintes cutanées spécifiques / formes chroniques <span class=\"q\">— traitements de fond (rang C)</span></strong></p><ul><li><span class=\"kw-ttt\">Dermocorticoïdes</span>, <span class=\"kw-ttt\">cyclines</span>, <span class=\"kw-ttt\">hydroxychloroquine</span></li><li><span class=\"kw-ttt\">Méthotrexate</span>, <span class=\"kw-ttt\">anti-TNFα (infliximab)</span></li></ul>","suivi":"<p><strong>Rythme de <span class=\"kw-def\">suivi</span></strong></p><ul><li>Patient revu tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-6 mois</span> jusqu'à la guérison</li><li>Forme aiguë <span class=\"kw-chiffre\">&lt; 2 ans</span> (Löfgren, <span class=\"kw-def\">stade</span> I) · forme chronique <span class=\"kw-chiffre\">≥ 3-5 ans</span></li></ul><p><strong>À chaque visite</strong></p><ul><li><span class=\"kw-clinique\">Examen ophtalmologique</span> + examen clinique complet</li><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">fonction rénale</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">ECA</span></li><li><span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-bio\">EFR</span>, <span class=\"kw-bio\">ECG</span></li></ul><p><strong><span class=\"kw-clinique\">Évolution</span></strong></p><ul><li><span class=\"kw-clinique\">Rémission</span> spontanée <span class=\"kw-chiffre\">&lt; 2 ans</span> dans <span class=\"kw-chiffre\">50 %</span> des cas ; très peu probable après <span class=\"kw-chiffre\">5 ans</span></li><li>Rechute le plus souvent <span class=\"kw-chiffre\">2-6 mois</span> après l'arrêt du traitement</li><li>Guérison = <span class=\"kw-clinique\">rémission</span> stable sans traitement pendant <span class=\"kw-chiffre\">3 ans</span></li></ul><p><strong><span class=\"kw-def\">Pronostic</span> global</strong></p><ul><li>Favorable <span class=\"kw-chiffre\">80 %</span> · séquelles <span class=\"kw-chiffre\">10-20 %</span> · décès <span class=\"kw-chiffre\">1-5 %</span></li></ul>"},"liensGlobaux":[{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_211_SARCOIDOSE-2023.pdf","label":"Collège (CEP) — Item 211 sarcoidose 2023"},{"href":"https://www.lecofer.org/item-cours-1-23-0.php","label":"Collège (COFER) — Item cours 1 23 0"},{"href":"https://radiopaedia.org/articles/sarcoidosis-1","label":"Radiopaedia : Sarcoidosis 1"},{"href":"https://radiopaedia.org/articles/l-fgren-syndrome","label":"Radiopaedia : L fgren syndrome"}],"cards":[{"i":"4767ef52f376","n":211,"o":"211-1","u":"Définition","t":"Connaître la définition de la sarcoïdose","q":"Quelle est la particularité histologique des granulomes de la sarcoïdose ?","a":"<p>Les granulomes sarcoïdiens sont formés de :</p><ul><li>Un <strong>follicule central</strong> avec des <strong>cellules épithélioïdes</strong>, des <strong>cellules géantes de Langhans</strong> (multinucléées, noyaux en couronne), et des <strong>lymphocytes T</strong>.</li><li>Une <strong>couronne périphérique</strong> avec un infiltrat lymphocytaire à prédominance <strong>LT CD4+</strong>.</li><li>L'absence de <strong>nécrose caséeuse</strong>, ce qui les distingue notamment des granulomes tuberculeux.</li></ul>"},{"i":"9fa81254f09e","n":211,"o":"211-1","u":"Définition","t":"Connaître la définition de la sarcoïdose","q":"Qu'est-ce que la sarcoïdose ?","a":"<p>La sarcoïdose est une <strong>granulomatose systémique</strong> de <strong>cause inconnue</strong>, caractérisée par l'infiltration des organes atteints par des <strong>granulomes immuns épithélioïdes et giganto-cellulaires sans nécrose caséeuse</strong>.</p>"},{"i":"b61542ed0074","n":211,"o":"211-1","u":"Définition","t":"Connaître la définition de la sarcoïdose","q":"Comment est posé le diagnostic de sarcoïdose ?","a":"<p>Le diagnostic de sarcoïdose est avant tout un <strong>diagnostic d'élimination</strong>, nécessitant d'écarter toutes les autres causes de granulomes.</p>"},{"i":"2e8f4cc628ba","n":211,"o":"211-4","u":"Diagnostic positif","t":"Connaître les critères du diagnostic d’une sarcoïdose","q":"Quelles précautions essentielles doivent être prises lors de l'analyse histologique d'une lésion suspecte de sarcoïdose afin d'éviter un piège diagnostique ?","a":"<p>Pour éviter le piège diagnostique de la tuberculose, toute pièce histologique doit faire l'objet de <strong>colorations spéciales (Ziehl)</strong> et d'une <strong>culture sur milieu de Löwenstein</strong>, afin d'éliminer formellement une tuberculose avant de retenir le diagnostic de sarcoïdose.</p>"},{"i":"67bc40ba154b","n":211,"o":"211-4","u":"Diagnostic positif","t":"Connaître les critères du diagnostic d’une sarcoïdose","q":"Quelle est l'aide au diagnostic apportée par le lavage broncho-alvéolaire (LBA) dans la sarcoïdose ?","a":"<p>Le LBA peut montrer une <strong>alvéolite lymphocytaire</strong> avec un rapport <strong>CD4/CD8 supérieur à 3,5</strong>, typique de la sarcoïdose.</p>"},{"i":"cdef4ea78d9a","n":211,"o":"211-4","u":"Diagnostic positif","t":"Connaître les critères du diagnostic d’une sarcoïdose","q":"Quels sites de prélèvement sont considérés de première intention pour l'obtention d'une preuve histologique dans la sarcoïdose ?","a":"<p>Les sites de prélèvement de première intention, peu invasifs, comprennent :</p><ul><li>Des lésions cutanées (sauf l'érythème noueux), cicatrices indurées, nodules conjonctivaux.</li><li>Des adénopathies périphériques, glandes salivaires accessoires, ou glandes lacrymales.</li><li>La ponction écho-guidée de ganglions médiastinaux.</li></ul>"},{"i":"d7333749270a","n":211,"o":"211-4","u":"Diagnostic positif","t":"Connaître les critères du diagnostic d’une sarcoïdose","q":"Sur quels critères majeurs repose le diagnostic de sarcoïdose ?","a":"<p>Le diagnostic de sarcoïdose repose sur un <strong>triptyque</strong> indissociable :</p><ul><li>Un tableau clinico-radiologique compatible.</li><li>La mise en évidence histologique de <strong>granulomes épithélioïdes et giganto-cellulaires sans nécrose caséeuse</strong>.</li><li>L'exclusion des autres granulomatoses (infectieuses, médicamenteuses, néoplasiques).</li></ul>"},{"i":"47f6f8b84cb3","n":211,"o":"211-5","u":"Diagnostic positif","t":"Connaître les formes fréquentes de la sarcoïdose : les atteintes respiratoires, le syndrome de Löfgren et l'érythème noueux","q":"Comment se manifeste l'érythème noueux dans le contexte de la sarcoïdose ?","a":"<p>L'érythème noueux est une manifestation cutanée non spécifique, dont la sarcoïdose est la 1ère cause en France. Il se présente sous forme de <strong>nouures</strong> (nodules hypodermiques) sur les <strong>faces d'extension des jambes</strong>, en régions prétibiales.</p><ul><li>Apparition aiguë.</li><li>Lésions <strong>bilatérales</strong>, fermes, <strong>douloureuses</strong>, chaudes.</li><li>Évolution biphasique des couleurs en 2-3 semaines : <strong>bleu-violet → vert-jaune → brun</strong>.</li></ul><p>Le diagnostic est clinique, une biopsie cutanée n'étant généralement pas nécessaire.</p>"},{"i":"7a532c7f4d4d","n":211,"o":"211-5","u":"Diagnostic positif","t":"Connaître les formes fréquentes de la sarcoïdose : les atteintes respiratoires, le syndrome de Löfgren et l'érythème noueux","q":"Qu'est-ce que le syndrome de Löfgren dans le cadre de la sarcoïdose, et quels en sont ses signes caractéristiques ?","a":"<p>Le syndrome de Löfgren est une <strong>forme aiguë et inflammatoire de sarcoïdose</strong>, de bon pronostic, touchant surtout la femme européenne.</p><p>Ses signes caractéristiques sont résumés par le moyen mnémotechnique FANTA :</p><ul><li><strong>F</strong>ièvre (rare en dehors de ce syndrome).</li><li><strong>A</strong>rthralgies / arthrites des chevilles (atteinte bilatérale quasi constante).</li><li><strong>N</strong>ouds ou <strong>N</strong>ouures d'érythème <strong>N</strong>oueux.</li><li><strong>T</strong>anergie <strong>T</strong>uberculinique.</li><li><strong>A</strong>dénopathies hilaires bilatérales et médiastinales.</li></ul><p>Le pronostic est excellent avec une résolution spontanée dans 90% des cas en moins de 2 ans.</p>"},{"i":"af30d91600a4","n":211,"o":"211-5","u":"Diagnostic positif","t":"Connaître les formes fréquentes de la sarcoïdose : les atteintes respiratoires, le syndrome de Löfgren et l'érythème noueux","q":"Quels sont les différents stades radiologiques de l'atteinte médiastino-pulmonaire de la sarcoïdose ?","a":"<ul><li><strong>Stade 0</strong> (10-20%) : Radiographie thoracique normale (formes extra-thoraciques pures).</li><li><strong>Stade I</strong> (50%) : <strong>Adénopathies hilaires bilatérales et médiastinales</strong>, sans atteinte parenchymateuse (bilatérales, symétriques, non compressives).</li><li><strong>Stade II</strong> : Adénopathies et atteinte parenchymateuse pulmonaire.</li><li><strong>Stade III</strong> (25%) : Atteinte parenchymateuse isolée (sans adénopathie), sous forme de <strong>micronodules diffus</strong>.</li><li><strong>Stade IV</strong> (5-8%) : <strong>Fibrose pulmonaire</strong> (opacités rétractiles, distorsion, ascension des hiles).</li></ul>"},{"i":"ff15fb0ed6e5","n":211,"o":"211-5","u":"Diagnostic positif","t":"Connaître les formes fréquentes de la sarcoïdose : les atteintes respiratoires, le syndrome de Löfgren et l'érythème noueux","q":"Comment se manifeste l'atteinte médiastino-pulmonaire de la sarcoïdose, et quelles sont ses caractéristiques cliniques principales ?","a":"<p>L'atteinte médiastino-pulmonaire est la forme la plus fréquente de la sarcoïdose (90% des patients), caractérisée par un contraste entre la <strong>pauvreté clinique</strong> et la <strong>richesse radiologique</strong>.</p><ul><li>Signes fonctionnels discrets : <strong>asthénie</strong>, <strong>toux non productive</strong> (fréquente), dyspnée (tardive), douleurs thoraciques.</li><li>Examen physique pauvre : hippocratisme digital et rares crépitants des bases sont possibles, mais l'auscultation est le plus souvent normale.</li></ul>"},{"i":"4b34b8ae9ae3","n":211,"o":"211-8","u":"Contenu multimédia","t":"Photographie d’un exemple typique d’érythème noueux","q":"Quelles sont les caractéristiques des nouures d'érythème noueux à la palpation et lors de leur évolution ?","a":"<p>Les nouures sont <strong>douloureuses</strong>, chaudes, et adhérentes aux plans superficiel et profond. Leur évolution est <strong>biphasique en 2 à 3 semaines</strong>, avec un changement de couleur : <strong>bleu-violet</strong>, puis <strong>vert-jaune</strong>, et enfin <strong>brun</strong>.</p>"},{"i":"85a92307c51a","n":211,"o":"211-8","u":"Contenu multimédia","t":"Photographie d’un exemple typique d’érythème noueux","q":"L'érythème noueux est-il spécifique d'une pathologie et une biopsie cutanée est-elle nécessaire pour le diagnostic ?","a":"<p>Le diagnostic d'érythème noueux est <strong>clinique</strong>. Ce n'est pas une lésion spécifique et une <strong>biopsie cutanée n'est pas nécessaire</strong>. En France, la <strong>sarcoïdose</strong> est la première cause d'érythème noueux inaugural.</p>"},{"i":"d254e4646cf9","n":211,"o":"211-8","u":"Contenu multimédia","t":"Photographie d’un exemple typique d’érythème noueux","q":"Quelle est la prise en charge symptomatique de l'érythème noueux ?","a":"<p>La prise en charge symptomatique de l'érythème noueux comprend le <strong>repos</strong>, la <strong>contention élastique</strong>, et des traitements médicamenteux comme les <strong>AINS</strong> (anti-inflammatoires non stéroïdiens) ou la <strong>colchicine</strong>.</p>"},{"i":"dae5bae5cd6a","n":211,"o":"211-8","u":"Contenu multimédia","t":"Photographie d’un exemple typique d’érythème noueux","q":"Comment l'érythème noueux se présente-t-il cliniquement, en termes de morphologie et de topographie ?","a":"<p>L'érythème noueux se caractérise par des <strong>nouures</strong> (nodules hypodermiques sous-cutanés), d'apparition aiguë, souvent <strong>bilatérales</strong>. Elles sont fermes, non fluctuantes, en relief, et prédominent sur les <strong>faces d'extension des membres inférieurs</strong> (régions prétibiales et genoux).</p>"},{"i":"f2d5df406286","n":211,"o":"211-8","u":"Contenu multimédia","t":"Photographie d’un exemple typique d’érythème noueux","q":"Quelles sont les principales causes d'érythème noueux, notamment la première en France ?","a":"<p>Les principales causes sont :</p><ul><li><strong>Sarcoïdose</strong> (1ère cause en France)</li><li><strong>Yersiniose</strong></li><li><strong>Streptocoque β-hémolytique</strong> du groupe A</li><li><strong>Tuberculose</strong></li><li><strong>Grossesse</strong></li><li><strong>Médicaments</strong></li><li><strong>Entérocolopathies</strong> (maladie de Crohn, RCH)</li><li><strong>Behçet</strong></li><li>Lèpre</li><li>Cancers, Chlamydia</li><li>Environ <strong>50%</strong> des cas sont <strong>idiopathiques</strong></li></ul>"}]};